import time
from datetime import datetime, timezone

OUTPUT = "/Users/ammar/Documents/codes/automations/browser-harness/x-for-you-100.json"
TARGET = 100
seen = {}
last_report = 0
stalled = 0

extract_js = r'''(() => [...document.querySelectorAll('article[data-testid="tweet"]')].map((a) => {
  const hrefs = [...a.querySelectorAll('a[href*="/status/"]')].map(x => x.getAttribute('href') || '');
  const canonical = hrefs.map(h => h.match(/^\/([^/]+)\/status\/(\d+)/)).find(Boolean);
  if (!canonical) return null;
  const userText = a.querySelector('[data-testid="User-Name"]')?.innerText || '';
  const lines = userText.split('\n').map(x => x.trim()).filter(Boolean);
  const handle = lines.find(x => x.startsWith('@')) || ('@' + canonical[1]);
  const displayName = lines.find(x => !x.startsWith('@') && x !== '·') || canonical[1];
  const imgs = [...a.querySelectorAll('img')].map(x => x.currentSrc || x.src || '').filter(src => src.includes('pbs.twimg.com/media/'));
  const videos = [...a.querySelectorAll('video')].map(x => x.poster || '').filter(Boolean);
  const otherStatuses = hrefs.map(h => {
    const m = h.match(/^\/([^/]+)\/status\/(\d+)/);
    return m ? `https://x.com/${m[1]}/status/${m[2]}` : '';
  }).filter(Boolean);
  const metric = (name) => a.querySelector(`[data-testid="${name}"]`)?.getAttribute('aria-label') || '';
  return {
    id: canonical[2],
    url: `https://x.com/${canonical[1]}/status/${canonical[2]}`,
    author_name: displayName,
    author_handle: handle,
    text: a.querySelector('[data-testid="tweetText"]')?.innerText || '',
    datetime: a.querySelector('time')?.getAttribute('datetime') || '',
    reply_metric: metric('reply'),
    repost_metric: metric('retweet') || metric('unretweet'),
    like_metric: metric('like') || metric('unlike'),
    bookmark_metric: metric('bookmark') || metric('removeBookmark'),
    view_metric: [...a.querySelectorAll('a[href$="/analytics"]')].map(x => x.getAttribute('aria-label') || x.innerText || '').find(Boolean) || '',
    media_urls: [...new Set([...imgs, ...videos])],
    quoted_status_urls: [...new Set(otherStatuses.filter(x => !x.endsWith(`/status/${canonical[2]}`)))],
    promoted: /(^|\n)(Ad|Promoted)(\n|$)/.test(a.innerText),
    raw_text: a.innerText
  };
}).filter(Boolean))()'''

print("COLLECTION_START", current_tab())
print("TARGET", TARGET)
for iteration in range(180):
    current = current_tab()
    if not current.get("url", "").startswith("https://x.com/home"):
        raise RuntimeError(f"X target changed unexpectedly: {current}")

    rows = js(extract_js)
    before = len(seen)
    for row in rows:
        if row["promoted"] or not row["id"]:
            continue
        if row["id"] not in seen:
            row["position"] = len(seen) + 1
            row["collected_at"] = datetime.now(timezone.utc).isoformat()
            seen[row["id"]] = row
            preview = re.sub(r"\s+", " ", row["text"] or row["raw_text"])[:160]
            print(f"COLLECTED {len(seen):03d} {row['author_handle']} {row['url']} | {preview}")
            if len(seen) >= TARGET:
                break

    if len(seen) >= TARGET:
        break

    if len(seen) == before:
        stalled += 1
    else:
        stalled = 0

    if len(seen) // 10 > last_report:
        last_report = len(seen) // 10
        info = page_info()
        print("PROGRESS", len(seen), "ITERATION", iteration, "SCROLL_Y", info.get("sy"), "PAGE_HEIGHT", info.get("ph"))

    try:
        scroll(840, 690, dy=1050)
    except Exception as exc:
        print("SCROLL_EXCEPTION", repr(exc))
        activate_tab(current_tab())
        scroll(840, 690, dy=1050)
        print("SCROLL_RETRY_AFTER_ACTIVATE")
    time.sleep(0.55 if stalled < 4 else 1.5)

    if stalled >= 12:
        print("STALL_RECOVERY", len(seen), "ITERATION", iteration)
        press_key("End")
        time.sleep(2)
        stalled = 0

